declare(strict_types=1);require_once __DIR__.'/migration-runner.php';
function app_apply_update(string $manifestUrl):array{if((string)envv('APP_MODE','hosted')!=='hosted')throw new RuntimeException('Online updater is disabled in Offline mode.');if(!class_exists('ZipArchive'))throw new RuntimeException('ZIP extension is required.');$raw=@file_get_contents($manifestUrl);$m=is_string($raw)?json_decode($raw,true):null;if(!is_array($m)||empty($m['url'])||empty($m['sha256'])||empty($m['version']))throw new RuntimeException('Invalid update manifest.');$tmp=v10_storage_dir('imports').'/update-'.bin2hex(random_bytes(8)).'.zip';$zipData=@file_get_contents((string)$m['url']);if($zipData===false||file_put_contents($tmp,$zipData,LOCK_EX)===false)throw new RuntimeException('Update download failed.');if(!hash_equals(strtolower((string)$m['sha256']),hash_file('sha256',$tmp))){@unlink($tmp);throw new RuntimeException('Update SHA-256 mismatch.');}$backup=v10_storage_dir('backups').'/pre-update-'.date('Ymd-His').'.zip';$bz=new ZipArchive();$bz->open($backup,ZipArchive::CREATE|ZipArchive::OVERWRITE);$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator(APP_ROOT,FilesystemIterator::SKIP_DOTS));foreach($it as$f){$rel=str_replace('\\','/',substr($f->getPathname(),strlen(APP_ROOT)+1));if($f->isFile()&&!str_starts_with($rel,'storage/')&&$rel!=='.env')$bz->addFile($f->getPathname(),$rel);}$bz->close();$extract=v10_storage_dir('imports').'/update-'.bin2hex(random_bytes(8));mkdir($extract,0700,true);$z=new ZipArchive();if($z->open($tmp)!==true)throw new RuntimeException('Cannot open update archive.');$z->extractTo($extract);$z->close();$entries=array_values(array_filter(scandir($extract)?:[],fn($x)=>$x!=='.'&&$x!=='..'));$src=count($entries)===1&&is_dir($extract.'/'.$entries[0])?$extract.'/'.$entries[0]:$extract;$iter=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($src,FilesystemIterator::SKIP_DOTS),RecursiveIteratorIterator::SELF_FIRST);foreach($iter as$f){$rel=str_replace('\\','/',substr($f->getPathname(),strlen($src)+1));if($rel==='.env'||str_starts_with($rel,'storage/'))continue;$dest=APP_ROOT.'/'.$rel;if($f->isDir()){if(!is_dir($dest))mkdir($dest,0770,true);}else{if(!is_dir(dirname($dest)))mkdir(dirname($dest),0770,true);if(!copy($f->getPathname(),$dest))throw new RuntimeException('Failed replacing '.$rel);}}$applied=migration_run(db());@unlink($tmp);return['version'=>$m['version'],'sha256'=>$m['sha256'],'backup'=>$backup,'migrations'=>$applied];}
